programlisting.code:
Create Spacecraft aSat aSat.ModelFile = '../data/vehicle/models/aura.3ds' aSat.ModelOffsetX = 1.5 aSat.ModelOffsetY = -2 aSat.ModelOffsetZ = 3 aSat.ModelRotationX = 180 aSat.ModelRotationY = 180 aSat.ModelRotationZ = 90 aSat.ModelScale = 15
Create Propagator aProp
Create OrbitView anOrbitView anOrbitView.Add = {aSat, Earth}
BeginMissionSequence Propagate aProp(aSat) {aSat.ElapsedSecs = 9000}
